<?php require_once __DIR__.'/../funciones.php'; exigir_admin();if($_SERVER['REQUEST_METHOD']==='POST'){$tipo=$_POST['tipo']??'';$accion=$_POST['accion']??'';$nombre=trim($_POST['nombre']??'');if($accion==='agregar'&&$nombre!==''){if($tipo==='pago'){$q=$conn->prepare('INSERT INTO metodos_pago(nombre) VALUES(?)');$q->bind_param('s',$nombre);$q->execute();}elseif($tipo==='envio'){$costo=(float)($_POST['costo']??0);$q=$conn->prepare('INSERT INTO metodos_envio(nombre,costo) VALUES(?,?)');$q->bind_param('sd',$nombre,$costo);$q->execute();}aviso('Método agregado.');}elseif($accion==='estado'){$id=(int)$_POST['id'];if($tipo==='pago')$q=$conn->prepare('UPDATE metodos_pago SET activo=1-activo WHERE id=?');else $q=$conn->prepare('UPDATE metodos_envio SET activo=1-activo WHERE id=?');$q->bind_param('i',$id);$q->execute();aviso('Disponibilidad actualizada.');}header('Location: configuracion.php');exit;}$pagos=$conn->query('SELECT * FROM metodos_pago ORDER BY id');$envios=$conn->query('SELECT * FROM metodos_envio ORDER BY id');?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pagos y envíos</title><link rel="stylesheet" href="../estilos.css"></head><body><?php include 'menu.php';?><main class="contenedor"><h1 class="titulo">Métodos de pago y envío</h1><?php mostrar_aviso();?><div class="tarjetas"><section class="panel"><h2 class="titulo">Métodos de pago</h2><form method="post"><input type="hidden" name="tipo" value="pago"><input type="hidden" name="accion" value="agregar"><div class="campo"><label>Nuevo método</label><input name="nombre" required placeholder="Ej. Tarjeta al recibir"></div><button class="btn">Agregar método</button></form><table><tr><th>Método</th><th>Estado</th><th>Acción</th></tr><?php while($p=$pagos->fetch_assoc()):?><tr><td><?=e($p['nombre'])?></td><td><?=$p['activo']?'Activo':'Inactivo'?></td><td><form method="post"><input type="hidden" name="tipo" value="pago"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-claro">Activar / Desactivar</button></form></td></tr><?php endwhile;?></table></section><section class="panel"><h2 class="titulo">Métodos de envío</h2><form method="post"><input type="hidden" name="tipo" value="envio"><input type="hidden" name="accion" value="agregar"><div class="campo"><label>Nombre del método</label><input name="nombre" required placeholder="Ej. Delivery express"></div><div class="campo"><label>Costo (S/)</label><input type="number" name="costo" min="0" step="0.01" value="0" required></div><button class="btn">Agregar método</button></form><table><tr><th>Método</th><th>Costo</th><th>Estado</th><th>Acción</th></tr><?php while($m=$envios->fetch_assoc()):?><tr><td><?=e($m['nombre'])?></td><td>S/ <?=number_format($m['costo'],2)?></td><td><?=$m['activo']?'Activo':'Inactivo'?></td><td><form method="post"><input type="hidden" name="tipo" value="envio"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-claro">Activar / Desactivar</button></form></td></tr><?php endwhile;?></table></section></div></main></body></html>
